-- Passage rg8-theme-summary-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('101762e6-c650-57d3-aaf8-72335aace1a3', 'rg8-theme-summary-p05', (select id from public.skills where slug = 'read-g8-theme-summary'), null,
        '6-8', $q$Last Across the Line$q$, $q$The starting horn is louder than I thought.
The pack takes off like birds from a wire.
By the second turn, I only see their backs.
By the third, I only hear the crowd.

My lungs are burning, and my shoes are lead.
A voice inside me says that I could stop.
No one would blame me. No one keeps a list
of runners who will never reach the top.

But Coach once said the clock is not the race.
The race is every step you choose to take.
So I count steps: a hundred, then a hundred more,
until the counting is the only thing awake.

My legs slow down, but still I do not walk.
I pass the bench, the banner, and the gate.
The sun is low and gold along the track,
and I keep going, even this late.

The stands are half empty when I come through.
A few still clap. My little sister cheers.
I am the last across the line today.
I finished what I started. That part is mine.$q$, 'draft')
